query($account: string!, $database: string!, $namespace: string!, $start: Time!, $end: Time!) {
 viewer { accounts(filter: {accountTag: $account}) {
  d1AnalyticsAdaptiveGroups(limit: 1000, filter: {databaseId: $database, datetime_geq: $start, datetime_lt: $end}, orderBy: [datetimeMinute_ASC]) {
   dimensions {datetimeMinute} sum {rowsRead rowsWritten readQueries writeQueries} avg {sampleInterval}
  }
  durableObjectsPeriodicGroups(limit: 1000, filter: {namespaceId: $namespace, datetime_geq: $start, datetime_lt: $end}, orderBy: [datetimeMinute_ASC]) {
   dimensions {datetimeMinute} sum {cpuTime inboundWebsocketMsgCount outboundWebsocketMsgCount exceededCpuErrors fatalInternalErrors}
  }
 } }
}
